// Extract fields from Slack Events API payload
// Slack wraps messages under body.event, not body directly
const body = $input.item.json.body || $input.item.json;
const event = body.event || {};

// Ignore retried events that we may have already processed
// (Slack adds X-Slack-Retry-Num header on retries, but we handle via event_id dedup in Supabase)

// Skip bot messages to prevent infinite loops
if (event.bot_id || event.subtype === 'bot_message') {
  return null;
}

// Only process standard user messages
if (event.type !== 'message' || !event.text) {
  return null;
}

return {
  json: {
    message_text: event.text,
    user_id: event.user || 'anonymous',
    channel_id: event.channel || '',
    source: 'slack',
    event_id: body.event_id || '',
    timestamp: event.ts
      ? new Date(parseFloat(event.ts) * 1000).toISOString()
      : new Date().toISOString(),
    metadata: {}
  }
};

// Route /tag commands to WF-05 instead of processing as content
const msg = $input.item.json;
const text = (msg.message_text || '').trim();
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';

// ── /slowest-tag: tag entry AND fire WF-02 crosslink re-run ──
const slowTagMatch = text.match(/^\/slowest-tag\s+(\S+)\s+(\S+)\s+(.+)$/i);
if (slowTagMatch || text === '/slowest-tag' || text.startsWith('/slowest-tag ') || text.startsWith('/slowest-tag\t')) {
  if (slowTagMatch) {
    const [, stFileName, stField, stValuesStr] = slowTagMatch;
    const stValues = stValuesStr.trim().split(/\s+/).filter(Boolean);
    const VALID_FIELDS = ['tags', 'entities', 'narrative_role'];
    const VALID_ROLES = ['realisation','exploration','conflict','symbol','system','orphaned'];

    let errMsg = null;
    if (!VALID_FIELDS.includes(stField)) {
      errMsg = `:x: Campo inválido: \`${stField}\`\n*Campos válidos:* \`narrative_role\` · \`tags\` · \`entities\``;
    } else if (stField === 'narrative_role' && !VALID_ROLES.includes(stValues[0])) {
      errMsg = `:x: Rol inválido: \`${stValues[0]}\`\n*Roles válidos:* \`${VALID_ROLES.join('\` · \`')}\``;
    }

    if (errMsg) {
      await this.helpers.httpRequest({
        method: 'POST', url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
        headers: {'Content-Type': 'application/json'}, body: {text: errMsg}, json: true
      });
      return null;
    }

    // 1. Apply tag via tag_entry() RPC
    let tagResult = {};
    try {
      tagResult = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/tag_entry',
        headers: {'apikey': ANON, 'Authorization': 'Bearer ' + ANON, 'Content-Type': 'application/json'},
        body: {p_file_name: stFileName, p_field: stField, p_values: stValues}, json: true
      });
    } catch(e) { tagResult = {status: 'error', message: e.message}; }

    if (tagResult.status === 'ok') {
      const cl = tagResult.crosslink || {};
      const crosslinkInfo = cl.related_count > 0 ? ` · :link: ${cl.related_count} conexiones` : ' · :white_circle: sin conexiones aún';
      const valDisplay = stValues.map(v => '`' + v + '`').join(' ');
      const fieldEmoji = {tags: ':label:', entities: ':bust_in_silhouette:', narrative_role: ':spiral_note_pad:'};
      const emoji = fieldEmoji[stField] || ':white_check_mark:';

      // 2. Post confirmation to Slack
      await this.helpers.httpRequest({
        method: 'POST', url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
        headers: {'Content-Type': 'application/json'},
        body: {text: `${emoji} *Tag aplicado* (vía /slowest-tag)\n*Entrada:* \`${stFileName}\`\n*Campo:* \`${stField}\` → ${valDisplay}${crosslinkInfo}\n_Crosslink ejecutado · :seedling: WF-02 re-run disparado_`},
        json: true
      });

      // 3. Fire WF-02 crosslink re-run (fire-and-forget)
      this.helpers.httpRequest({
        method: 'POST', url: 'https://n8n-docker-t9sr.onrender.com/webhook/wf02-crosslink',
        headers: {'Content-Type': 'application/json'},
        body: {file_name: stFileName, source: 'slack_slowest_tag', user_id: msg.user_id || null}, json: true
      }).catch(() => {});

      // 4. Log to audit (fire-and-forget)
      this.helpers.httpRequest({
        method: 'POST', url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/log_tag_command',
        headers: {'apikey': ANON, 'Authorization': 'Bearer ' + ANON, 'Content-Type': 'application/json'},
        body: {p_file_name: stFileName, p_field: stField, p_values: stValues, p_slack_user_id: msg.user_id || null, p_channel_id: msg.channel_id || null, p_crosslink_count_after: (tagResult.crosslink || {}).related_count || 0}, json: true
      }).catch(() => {});

    } else {
      await this.helpers.httpRequest({
        method: 'POST', url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
        headers: {'Content-Type': 'application/json'},
        body: {text: `:x: *Error al aplicar /slowest-tag*\n\`${stFileName}\` — ${tagResult.message || 'Error desconocido'}`}, json: true
      });
    }
  } else {
    // No args — show usage
    await this.helpers.httpRequest({
      method: 'POST', url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
      headers: {'Content-Type': 'application/json'},
      body: {text: ':seedling: *Uso:* `/slowest-tag <file_name> <field> <valores>`\n\n_Aplica el tag Y dispara crosslink re-run vía WF-02._\n\nEjemplos:\n`/slowest-tag TSW_ea_geometry entities NEYEN`\n`/slowest-tag TSW_ea_portal tags geometria espiral`\n`/slowest-tag TSW_libro_0 narrative_role inciting_event`\n\n*Campos válidos:* `narrative_role` · `tags` · `entities`'}, json: true
    });
  }
  return null;
}

// Check for all WF-05/WF-06 commands
if (text.startsWith('/tag ') || text.startsWith('/tag\t') || text === '/graph' || text.startsWith('/graph ') || text.startsWith('/history ') || text.startsWith('/history\t') || text.startsWith('/compare ') || text.startsWith('/compare\t') || text.startsWith('/trend ') || text.startsWith('/trend\t') || text === '/leaderboard' || text.startsWith('/leaderboard ') || text.startsWith('/leaderboard\t')) {
  const isSearch = false; // these all go to WF-05
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n-docker-t9sr.onrender.com/webhook/wf05-slack-tagger',
    headers: {'Content-Type': 'application/json'},
    body: {body: {text: text, user_id: msg.user_id || '', channel_id: msg.channel_id || '', ts: msg.timestamp || ''}},
    json: true
  }).catch(() => {});
  return null;
}

// /search goes to WF-06
if (text.startsWith('/search ') || text.startsWith('/search\t')) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n-docker-t9sr.onrender.com/webhook/wf06-search',
    headers: {'Content-Type': 'application/json'},
    body: {body: {text: text, user_id: msg.user_id || '', channel_id: msg.channel_id || '', ts: msg.timestamp || ''}},
    json: true
  }).catch(() => {});
  return null;
}

// Not a slash command — pass through normally
return { json: msg };

// Build the Claude API request body with narrative_role classifier
const messageText = $input.item.json.message_text || '';
const source = $input.item.json.source || 'unknown';
const timestamp = $input.item.json.timestamp || new Date().toISOString();

// Role definitions for accurate classification
const roleGuide = `
- realisation: insight, breakthrough, understanding, clarity, epiphany, aha-moment
- exploration: question, curiosity, investigation, research, trying, experimenting
- conflict: tension, problem, contradiction, difficulty, obstacle, error
- symbol: metaphor, archetype, image, myth, spiritual, dream, ceremony
- system: architecture, structure, tool, process, rule, protocol, design
- orphaned: DO NOT assign this — reserved for entries with no crosslinks after 7 days
`.trim();

const prompt = `Analyze this Slack message and extract NEYEN knowledge graph metadata.

Message: ${messageText}
Source: ${source}
Timestamp: ${timestamp}

Return ONLY valid JSON (no markdown, no explanation):
{
  "tags": ["tag1", "tag2", "tag3"],
  "entities": ["entity1", "entity2"],
  "summary": "1-2 sentence summary",
  "narrative_role": "one of the 6 roles below",
  "date_estimated": "YYYY-MM-DD or YYYY",
  "timeline_group": "1974-1990|2019-2023|2024-2026"
}

Narrative role — choose EXACTLY one (never use orphaned):
${roleGuide}

Rules:
- tags: 3-5 lowercase keywords capturing the core topic
- entities: named people, companies, systems, or key concepts
- summary: factual, present-tense, max 2 sentences
- narrative_role: best fit from the 6 options above — if unclear, choose exploration
- date_estimated: infer from message context or use the timestamp date
- timeline_group: map to the closest period`;

return {
  json: {
    ...$input.item.json,
    claudeRequestBody: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 1024,
      messages: [{ role: 'user', content: prompt }]
    })
  }
};

// Parse Claude API response
const response = $input.item.json;
const content = response.content && response.content[0] && response.content[0].text;

if (!content) {
  throw new Error('No content in Claude response');
}

// Strip markdown code fences if Claude added them
let jsonText = content.trim();
if (jsonText.startsWith('```json')) {
  jsonText = jsonText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
} else if (jsonText.startsWith('```')) {
  jsonText = jsonText.replace(/```\n?/g, '').trim();
}

const classified = JSON.parse(jsonText);

// Pull original message data from Extract Content node
const originalData = $node['Extract Content'].json;

// Generate a stable file_name using event_id when available
const suffix = originalData.event_id || new Date().getTime();
const file_name = `auto_slack_${suffix}`;

return {
  json: {
    file_name: file_name,
    type: null,
    summary: classified.summary || '',
    tags: classified.tags || [],
    entities: classified.entities || [],
    emotional_tone: null,
    source: originalData.source,
    themes: [],
    concepts: [],
    keywords: [],
    mime_type: 'text/plain',
    cluster: null,
    related_ids: [],
    date_estimated: classified.date_estimated || new Date().toISOString().split('T')[0],
    timeline_group: classified.timeline_group || '2024-2026',
    narrative_role: classified.narrative_role || 'exploration'
  }
};
